import{_ as a,o as i,c as o,a0 as t}from"./chunks/framework.C4u0TEY0.js";const u=JSON.parse('{"title":"简介","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/introduction.md","filePath":"zh/guide/introduction.md"}'),d={name:"zh/guide/introduction.md"};function r(l,e,c,n,s,h){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h1><p>apk.js 用纯 JavaScript 在浏览器里运行 Android APK。它读取 APK、执行应用字节码，再把生成的界面画到 Canvas 上，不需要设备、模拟器或原生库。</p><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>APK 是一个 zip 包，apk.js 从中取出五类内容：</p><ol><li><code>classes.dex</code>：应用字节码，交给 DEX 解释器执行。</li><li><code>AndroidManifest.xml</code>：二进制 AXML，描述包名、Activity 和主题。</li><li><code>resources.arsc</code>：资源表，把资源 ID 解析成字符串、颜色和文件路径。</li><li><code>res/</code> 下的文件：布局和可绘制资源，同样是二进制 AXML。</li><li><code>assets/</code> 下的文件：应用资源，通过运行时提供。</li></ol><p>解释器遇到 Android API 调用时，会转交给 Canvas 支撑的 Framework 实现。应用调用 <code>setContentView</code>、加载布局或测量视图时，这些调用都落在 Framework 子集里，由它决定如何画到 canvas 上。</p><h2 id="能跑什么" tabindex="-1">能跑什么 <a class="header-anchor" href="#能跑什么" aria-label="Permalink to &quot;能跑什么&quot;">​</a></h2><p>项目面向中小型 Java/Kotlin 应用。示例 <code>hello-dex.apk</code> 涵盖计数、文本输入、动态视图、进度条、形状背景、<code>Build</code> 信息、反射和多 Activity 跳转。</p><p>真实应用也能跑。<code>image-debug/devinfo.png</code> 就是一个硬件信息应用经过解释器后的渲染结果。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/apk.js/zh/guide/quick-start.html">快速开始</a>：先把演示跑起来。</li><li><a href="/apk.js/zh/guide/embedding.html">嵌入页面</a>：把模拟器放进你自己的页面。</li><li><a href="/apk.js/zh/internals/architecture.html">架构</a>：各部分如何配合。</li></ul>',11)])])}const m=a(d,[["render",r]]);export{u as __pageData,m as default};
